Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "background": "transparent",
  "padding": 0,
  "width": "container",
  "height": "container",
  "config": {
    "view": {
      "stroke": null
    },
    "font": "Segoe UI",
    "axis": {
      "domain": false,
      "ticks": false,
      "gridColor": "rgba(255,255,255,0.06)",
      "labelColor": "#C8C8D0",
      "titleColor": "#C8C8D0",
      "labelFontSize": 10,
      "titleFontSize": 10
    }
  },
  "data": {
    "name": "dataset"
  },
  "transform": [
    {
      "fold": [
        "Clientes 1 Compra",
        "Clientes 2 Compras",
        "Clientes 3-4 Compras",
        "Clientes 5+ Compras"
      ],
      "as": [
        "estagio",
        "qtd"
      ]
    },
    {
      "calculate": "{''Clientes 1 Compra'':''1 compra'',''Clientes 2 Compras'':''2 compras'',''Clientes 3-4 Compras'':''3-4 compras'',''Clientes 5+ Compras'':''5+ compras''}[datum.estagio]",
      "as": "Estágio"
    },
    {
      "calculate": "{''Clientes 1 Compra'':1,''Clientes 2 Compras'':2,''Clientes 3-4 Compras'':3,''Clientes 5+ Compras'':4}[datum.estagio]",
      "as": "ord"
    }
  ],
  "encoding": {
    "y": {
      "field": "Estágio",
      "type": "nominal",
      "sort": {
        "field": "ord"
      },
      "title": null,
      "axis": {
        "labelFontSize": 10
      }
    },
    "x": {
      "field": "qtd",
      "type": "quantitative",
      "title": null,
      "axis": {
        "format": ",.0s"
      }
    },
    "tooltip": [
      {
        "field": "Estágio",
        "title": "Etapa"
      },
      {
        "field": "qtd",
        "type": "quantitative",
        "format": ",.0f",
        "title": "Clientes"
      }
    ]
  },
  "layer": [
    {
      "mark": {
        "type": "bar",
        "cornerRadiusEnd": 4,
        "height": {
          "band": 0.7
        },
        "color": {
          "x1": 0,
          "y1": 0,
          "x2": 1,
          "y2": 0,
          "gradient": "linear",
          "stops": [
            {
              "offset": 0,
              "color": "#5E6AD2"
            },
            {
              "offset": 1,
              "color": "#A78BFA"
            }
          ]
        }
      },
      "encoding": {
        "opacity": {
          "condition": {
            "test": "datum.__selected__ === ''off''",
            "value": 0.18
          },
          "value": 1
        }
      }
    },
    {
      "mark": {
        "type": "text",
        "align": "left",
        "dx": 4,
        "fontSize": 9,
        "color": "#C8C8D0"
      },
      "encoding": {
        "text": {
          "field": "qtd",
          "type": "quantitative",
          "format": ",.0f"
        },
        "opacity": {
          "condition": {
            "test": "datum.__selected__ === ''off''",
            "value": 0.18
          },
          "value": 1
        }
      }
    }
  ]
}'
